package cn.zhuatech.workforceai.controller; import cn.zhuatech.workforceai.common.ApiResponse; import cn.zhuatech.workforceai.dto.WorkforceAiDto.*; import cn.zhuatech.workforceai.service.WorkforceAiService; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import java.util.List;
@RestController @RequestMapping("/api/admin") @PreAuthorize("hasAnyRole('DOMAIN_OPERATOR','QUALITY','ADMIN')") public class OperationsAdminController {private final WorkforceAiService service;public OperationsAdminController(WorkforceAiService service){this.service=service;}@GetMapping("/dashboard") public ApiResponse<Dashboard> dashboard(){return ApiResponse.ok(service.adminDashboard());}@GetMapping("/work-orders") public ApiResponse<List<WorkRecordView>> orders(){return ApiResponse.ok(service.workRecords());}}
